using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class NpcCommunityAdministrationTests
{
    static readonly EntityId Kofu=new("site:kofu");
    internal static WorldSession Start(string person="person:nobunaga",ulong seed=1)=>new(NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],person,seed,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:NpcCommunityAdministration.Policy));
    static void Advance(WorldSession s,long at){while(s.Seconds<at){long old=s.Seconds;s.SetPaused(false);s.AdvanceTo(at,100000);Assert.True(s.Seconds>old);}}
    static long Day(int y,int m,int d)=>(new DateOnly(y,m,d).DayNumber-new DateOnly(1560,1,1).DayNumber)*86400L;
    static CommunityAccounts A(WorldSession s,EntityId? site=null)=>s.DiagnosticSnapshot().Communities!.Accounts.Single(a=>a.Site==(site??Kofu));
    static CommunityDecision[] Decisions(WorldSession s)=>s.DiagnosticSnapshot().CommunityAdministration!.Decisions;
    [Fact]public void NewWorldHasNoUnrequestedInitialSpending(){var s=Start();Assert.Empty(Decisions(s));Assert.Equal(3000,A(s).HouseRice);Assert.NotNull(s.VillageView());Assert.NotNull(s.SalaryView());Assert.NotNull(s.RegionalTradeView());}
    [Fact]public void MonthStartNpcOnlySpendsItsOwnActualRiceAndLabor(){var s=Start();Advance(s,Day(1560,2,1));Assert.Equal(2,Decisions(s).Length);Assert.All(Decisions(s),d=>Assert.NotEqual(s.PlayerControl,d.Actor));Assert.Equal(2800,A(s).HouseRice);Assert.Equal(20,A(s).Reserved);Assert.Equal(3000,A(s,new("site:castle")).HouseRice);Assert.All(Decisions(s),d=>Assert.NotNull(d.Representative));}
    [Fact]public void RepeatedAdvanceWithinMonthCannotDuplicateDecisionOrSpending(){var s=Start();Advance(s,Day(1560,2,1));Advance(s,Day(1560,2,2));Assert.Equal(2,Decisions(s).Length);Assert.Equal(2800,A(s).HouseRice);}
    [Fact]public void WorkCompletesAndMonthlyWorkStopsAtWaterLimit(){var s=Start();Advance(s,Day(1560,5,9));Assert.Equal(130,A(s).Water);Assert.Equal(0,A(s).Reserved);Assert.Equal(2400,A(s).HouseRice);Assert.Equal(3,Decisions(s).Count(d=>d.Site==Kofu&&d.Action==EconomyAction.ImproveWater));Assert.Null(Decisions(s).Last(d=>d.Site==Kofu).Action);}
    [Fact]public void ExistingLevyIsCollectedInBoundedPhysicalInstallments(){var s=Start();Advance(s,Day(1560,10,1));var account=A(s);Assert.True(account.Assessed>0);Assert.Equal(1000,account.Collected);var decision=Decisions(s).Last(d=>d.Site==Kofu);Assert.Equal(EconomyAction.CollectLevy,decision.Action);Assert.InRange(decision.Amount,1,1000);Assert.True(account.VillageRice>=1000);}
    [Fact]public void NpcCannotConsumePlayerHouseOrPrivateWallets(){var s=Start();var before=s.DiagnosticSnapshot();Advance(s,Day(1560,4,9));Assert.DoesNotContain(s.DiagnosticSnapshot().Communities!.Orders,o=>o.Actor==s.PlayerControl);Assert.Equal(3000,A(s,new("site:castle")).HouseRice);Assert.Equal(ContractJson.Write(before.ResourceLots),ContractJson.Write(s.DiagnosticSnapshot().ResourceLots));}
    [Fact]public void AbsentNpcHeadWaitsWithoutReadingLocalAccounts(){var w=NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],"person:shingen",1,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:NpcCommunityAdministration.Policy,worldArmyPolicy:NpcArmies.Policy);w.CommitSequence++;var muster=new EntityId("decision:absent-head");NpcArmies.Muster(w,muster,new("person:nobunaga"),new("org:oda"));var s=new WorldSession(w);Assert.Equal(ResultCode.Accepted,s.Submit(NpcArmies.Move(s.DiagnosticSnapshot(),muster,"request:head-away","fork"),s.Revision).Code);Advance(s,Day(1560,2,1));var d=Decisions(s).Single(d=>d.Site.Value=="site:castle");Assert.Null(d.Action);Assert.Equal(0,d.Amount);Assert.Contains("待機",d.Reason);Assert.Equal(3000,A(s,new("site:castle")).HouseRice);}
    [Fact]public void LocalOutcomeDoesNotExposeForeignDecisions(){var s=Start();Advance(s,Day(1560,2,1));var text=System.Text.Encoding.UTF8.GetString(ContractJson.Write(s.VillageView()));Assert.DoesNotContain("InputsHash",text);Assert.DoesNotContain("site:kofu",text);Assert.DoesNotContain("HouseRice",text);Assert.Equal("",s.VillageView()!.Administration);}
    [Fact]public void PlayerEmployeeSeesActualLocalWorkWithoutHouseInventory(){var s=Start(HistoricalHouseholdCatalog.Edition.People.Single().Id.Value);Advance(s,Day(1560,2,1));Assert.Contains("工事",s.VillageView()!.Administration);Assert.False(s.VillageView()!.CanPromise);Assert.DoesNotContain("HouseRice",System.Text.Encoding.UTF8.GetString(ContractJson.Write(s.VillageView())));}
    [Fact]public void PendingSalaryIsProtectedFromNpcReliefAndWork(){var s=Start(HistoricalHouseholdCatalog.Edition.People.Single().Id.Value);var head=new EntityId("person:shingen");Assert.Equal(ResultCode.Accepted,s.ManageSalary(new(new("request:npc-salary"),SalaryAction.Propose,head,Kofu,Amount:40),s.PlayerControl,s.Revision).Code);var q=s.DiagnosticSnapshot().Salary!.Quotes.Last().Id;Assert.Equal(ResultCode.Accepted,s.ManageSalary(new(new("request:npc-salary-confirm"),SalaryAction.Confirm,head,Kofu,q),s.PlayerControl,s.Revision).Code);Advance(s,Day(1560,2,1));Assert.Equal(40,s.SalaryView()!.Contracts.Single().Owed);Assert.Equal(ResultCode.Accepted,s.ManageSalary(new(new("request:npc-salary-prepare"),SalaryAction.Prepare,head,Kofu,q,40),s.PlayerControl,s.Revision).Code);Assert.Equal(40,s.SalaryView()!.Contracts.Single().Prepared);Advance(s,Day(1560,3,1)-1);Assert.Equal(ResultCode.Accepted,s.ManageSalary(new(new("request:npc-salary-ready"),SalaryAction.Prepare,head,Kofu,q,40),s.PlayerControl,s.Revision).Code);long free=A(s).HouseRice-40;Advance(s,Day(1560,3,1));Assert.Equal(40,s.SalaryView()!.Contracts.Single().Prepared);Assert.True(A(s).HouseRice>=40);Assert.True(Decisions(s).Last(d=>d.Site==Kofu).Amount<=free);}
    [Fact]public void PolicyAndLegacyV5AreExplicitAndByteStable(){var s=VillageConsultationTests.Start();var bytes=ContractJson.Write(s.DiagnosticSnapshot());Assert.DoesNotContain("CommunityAdministration",System.Text.Encoding.UTF8.GetString(bytes));Assert.Equal(bytes,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(bytes)).DiagnosticSnapshot()));var w=s.DiagnosticSnapshot();w.CommunityAdministration=Start().DiagnosticSnapshot().CommunityAdministration;Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void ForgedNpcDecisionCannotLoad(){var s=Start();Advance(s,Day(1560,2,1));var w=s.DiagnosticSnapshot();w.CommunityAdministration=w.CommunityAdministration! with{Decisions=[..w.CommunityAdministration.Decisions.Select(d=>d with{Amount=2999})]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void MissingDecisionCannotLeaveUnbackedRiceMovement(){var s=Start();Advance(s,Day(1560,2,1));var w=s.DiagnosticSnapshot();w.CommunityAdministration=w.CommunityAdministration! with{Decisions=[]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void NpcOriginalIdCannotBeReusedForPlayerOperation(){var s=Start();Advance(s,Day(1560,2,1));var id=Decisions(s).First().Id;Assert.Equal(ResultCode.IdPayloadConflict,s.ManageCommunity(new(id,new("site:castle"),EconomyAction.RelieveVillage,1),s.PlayerControl,s.Revision).Code);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]
    public void ActualGenerationRecoveryOfNpcWorkLevyAndLaterReliefPreservesFuture(int phase){var a=Start();Advance(a,phase==0?Day(1560,2,2):phase==1?Day(1560,10,1):Day(1562,8,1));a.SetPaused(true);var w=a.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"npc-community-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(a,"npc",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("npc"),host.Current,host.Current.Revision));var b=host.Current;Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,"npc-community-"+phase+".before.json"),ContractJson.Write(a.DiagnosticSnapshot()));File.WriteAllBytes(Path.Combine(dir,"npc-community-"+phase+".restored.json"),ContractJson.Write(b.DiagnosticSnapshot()));}Advance(a,a.Seconds+65*86400);Advance(b,b.Seconds+65*86400);Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));if(phase==2)Assert.Contains(Decisions(a),d=>d.Action==EconomyAction.RelieveVillage);}
    [Fact]public void MonthlyDecisionsAndAccountsIgnoreAdvanceChunkSize(){var a=Start();var b=Start();Advance(a,Day(1560,6,1));for(int m=2;m<=6;m++)Advance(b,Day(1560,m,1));Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot().CommunityAdministration),ContractJson.Write(b.DiagnosticSnapshot().CommunityAdministration));Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot().Communities!.Accounts),ContractJson.Write(b.DiagnosticSnapshot().Communities!.Accounts));}
    [Fact]public void NormalProfileBuildsLocalNpcAdministration(){var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"salary-profile-"+Guid.NewGuid().ToString("N")));var p=store.New(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],"person:shingen",42,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,NewGameNpcRoutine.Policy,LocalInspectionFindings.Policy,WorkFollowup.Policy,null,VoyageExpense.Standard,NpcArmies.CompactCombatPolicy,NpcCommunityAdministration.Policy,PersonalCompanions.RetainerReleasePolicy,TruceNegotiations.Policy,PrivateInformation.Policy,PrivateStanddown.Policy);Assert.Equal(NpcCommunityAdministration.Policy,store.Read(p.Instance).EconomyPolicy);var s=new WorldSession(NewCampaignStore.Build(p));Assert.NotNull(s.SalaryView());Assert.NotNull(s.CommunityEconomyView());Assert.NotNull(s.RegionalTradeView());Assert.NotNull(s.VillageView());Assert.Equal(3,s.DiagnosticSnapshot().Villages!.Organizations.Length);}
}
